#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

#ifdef __cplusplus
extern "C" {
#endif
int fuzz_parse_http_request(const uint8_t *data, size_t length);
#ifdef __cplusplus
}
#endif

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = (uint8_t*)malloc(len);
    fread(buf, 1, len, f);
    fclose(f);
    printf("Calling fuzz_parse_http_request with %ld bytes\n", len);
    int ret = fuzz_parse_http_request(buf, len);
    printf("Returned: %d\n", ret);
    free(buf);
    return 0;
}
EOF
